export default function f({ values, scheduledAt, previous }) {
  const rows = Array.isArray(values) ? values : [];
  if (rows.length < 2) return { state: { i: 0 }, more: false, body: {} };
  const headers = rows[0].map((h) => String(h || "").trim());
  const idx = (k) => headers.indexOf(k);
  const iId = idx("customer_id"),
    iMail = idx("user_mail"),
    iScore = idx("predicted_churn_score"),
    iCat = idx("preferred_categories");
  if (iId < 0 || iMail < 0 || iScore < 0 || iCat < 0)
    throw Error("Missing required columns in Customer Data");
  const eligible = [];
  for (let r = 1; r < rows.length; r++) {
    const row = rows[r] || [],
      s = Number(row[iScore] || 0);
    if (s > 0.7 && s <= 1 && row[iId] && row[iMail])
      eligible.push({
        customer_id: String(row[iId]),
        user_mail: String(row[iMail]),
        predicted_churn_score: s,
        preferred_categories: String(row[iCat] || ""),
        day: String(scheduledAt || "").slice(0, 10),
      });
  }
  const i = previous?.i ?? 0;
  const item = eligible[i];
  return { state: { i: i + 1 }, more: Boolean(item), body: item || {} };
}

