export default async function plan({ body, details, acknowledge, resolution }, ctx) {
  const id = String(body.customer_id || "").trim(),
    email = String(body.user_mail || "").trim(),
    score = Number(body.predicted_churn_score),
    day = String(body.day || "");
  if (
    !id ||
    !email ||
    !/^\d{4}-\d\d-\d\d$/.test(day) ||
    !Number.isFinite(score) ||
    score <= 0.7 ||
    score > 1
  )
    throw Error("Invalid customer, day or churn score");
  const key = "churn:" + day + ":" + id,
    old = await ctx.state.get(key);
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending email " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "sent" });
      return { send: false, key, to: email, details };
    }
  }
  if (old?.status === "sent" || old?.status === "logged" || old?.status === "log-pending")
    return { send: false, key, to: email, details };
  await ctx.state.set(key, { status: "pending" });
  return { send: true, key, to: email, details };
}

