export default async function plan({ key, body, acknowledge, resolution }, ctx) {
  let old = await ctx.state.get(key);
  if (old?.status === "logged") return { write: false, key, values: [] };
  if (old?.status === "log-pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending sheet log " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "logged" });
      return { write: false, key, values: [] };
    }
  } else if (old?.status !== "sent") throw Error("Email is not confirmed");
  await ctx.state.set(key, { status: "log-pending" });
  return {
    write: true,
    key,
    values: [[String(body.customer_id), "SENT_WINBACK_OFFER", new Date().toISOString()]],
  };
}

